DONE = {'provider': 'fetchMoreCountryStations', 'screen': '_chipBar(', 'player': 'radioProvider.streamTitle'}

results, ok = [], True
for k, path in FILES.items():
    raw = open(path, 'rb').read().decode('utf-8')
    crlf = '\r\n' in raw
    src = raw.replace('\r\n', '\n')
    if DONE[k] in src:
        print(f'{os.path.basename(path)}: 이미 적용돼 있어요'); continue
    for name, old, new in PLAN[k]:
        n = src.count(old)
        if n != 1:
            print(f'❌ {os.path.basename(path)} · {name}: 찾을 코드를 {"못 찾았어요" if n == 0 else f"{n}곳에서 찾았어요"}'); ok = False
        else:
            src = src.replace(old, new); print(f'✔ {os.path.basename(path)} · {name}')
    results.append((path, src.replace('\n', '\r\n') if crlf else src))
if not ok:
    print('아무것도 저장하지 않았어요'); sys.exit(1)
for path, out in results:
    open(path, 'wb').write(out.encode('utf-8')); print('저장했어요:', path)
